@font-face { font-family: Poppins-Medium; src: url("/_next/static/media/Poppins-Medium.1f5f6083.woff") format("woff"); }

@font-face { font-family: Poppins-SemiBold; src: url("/_next/static/media/Poppins-SemiBold.044deece.woff") format("woff"); }

@font-face { font-family: Poppins-Bold; src: url("/_next/static/media/Poppins-Bold.a26e3967.woff") format("woff"); }

@font-face { font-family: Poppins-Black; src: url("/_next/static/media/Poppins-Black.636b01a6.woff") format("woff"); }

