b, strong { font-family: Poppins-SemiBold; }

input[type="number"]::-webkit-inner-spin-button, input[type="number"]::-webkit-outer-spin-button { appearance: none; }

* { margin: 0px; font-family: Poppins-Regular; }

*, p { padding: 0px; color: rgb(51, 51, 51); font-size: 14px; line-height: 24px; }

p { margin: 0px 0px 15px; }

.container { margin: 0px auto; max-width: 90% !important; width: 100% !important; }

a, button { transition: 0.5s; }

input:focus, select:focus { outline: none; }

a, a:hover { text-decoration: none !important; }

.flex-class { display: flex; flex-flow: wrap; width: 100%; }

.container_new { max-width: 1366px; width: 100%; padding: 0px 15px; margin: 0px auto; }

.breadcrumb > .breadcrumb-item + .breadcrumb-item::before { content: " > "; }

header { background-color: rgb(32, 32, 32); padding: 15px 0px; position: relative; }

.header-row { align-items: center; }

.header-row .co-logo { width: 25%; }

.header-row .co-logo img { width: 165px; }

.header-row .searchbox { width: 50%; padding: 0px 15px; align-items: center; }

.header-row .header-right-col { width: 25%; text-align: right; }

.header-row .header-right-col .top-bar-menu { padding-bottom: 15px; }

.searchbox .search-col { width: calc(100% - 60px); }

.searchbox .search-col .form-group .search-input { width: 100%; background-color: rgb(255, 255, 255); border-width: medium; border-style: none; border-color: currentcolor; border-image: none; border-radius: 4px; height: 40px; padding: 0px 15px; }

.searchbox .search-col .form-group .search-input::placeholder { color: rgb(0, 0, 0); }

.searchbox .search-col .form-group .sear-btn { width: 40px; height: 40px; background-color: transparent; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; position: absolute; top: 0px; right: 0px; }

.searchbox .search-col .form-group .sear-btn img { height: 20px; }

.searchbox .cameraUpload { width: 60px; text-align: right; }

.searchbox .cameraUpload button { background-color: transparent; border-width: medium; border-style: none; border-color: currentcolor; border-image: none; }

.searchbox .cameraUpload img { max-width: 30px; }

.searchbox .search-col .form-group { margin: 0px; position: relative; }

.header-right-col .top-bar-menu ul { list-style: none; align-items: center; justify-content: right; margin: 0px; padding: 0px; }

.header-right-col .top-bar-menu ul li { padding-left: 15px; }

.header-right-col .top-bar-menu ul li a { color: rgb(255, 255, 255); }

.header-right-col .top-bar-menu ul li.help-call a { border: 1px solid transparent; padding: 4px 12px; border-radius: 30px; }

.header-right-col .top-bar-menu ul li.help-call a:hover { border: 1px solid rgb(255, 203, 8); background-color: rgb(255, 203, 8); color: rgb(51, 51, 51); }

.header-right-col .top-bar-menu ul li.help-call a:hover img { filter: brightness(0.2); }

.header-right-col .h-main-menu ul { list-style: none; align-items: center; justify-content: right; margin: 0px; padding: 0px; }

.header-right-col .h-main-menu ul li { padding-left: 30px; }

.header-right-col .h-main-menu ul li p { margin: 0px; }

.h-main-menu .cart-bx { position: relative; }

.h-main-menu .cart-bx span { background: rgb(255, 203, 55); width: 20px; height: 20px; display: inline-block; text-align: center; border-radius: 50%; line-height: 20px; font-size: 12px; position: absolute; right: -10px; top: -8px; z-index: 5; }

.h-main-menu .cart-bx span:hover { cursor: pointer; }

.header-right-col .h-main-menu ul li:first-child { padding-left: 0px; }

.header-right-col .h-main-menu ul li a { color: rgb(255, 255, 255); display: flex; flex-flow: wrap; align-items: center; line-height: normal; }

.header-right-col .h-main-menu ul li.cart-bx p img { height: 26px; filter: brightness(0) invert(1); }

.header-right-col .h-main-menu ul li img { height: 16px; }

.header-right-col .h-main-menu ul li a img { padding-right: 4px; }

.custom-head-mobile { display: none; }

.header-section.fixed .obl-nav-section { position: fixed; width: 100%; top: 0px; z-index: 9; }

#mobile_search_div { display: none; }

.mini_cart { width: 370px; z-index: 2; position: absolute; background: rgb(255, 255, 255); top: 90px; right: 80px; padding: 15px; box-shadow: rgba(0, 0, 0, 0.55) 0px 0px 5px; display: block; }

.mini_cart.close_min_cart { display: none; }

.mini_cart .btn.btn-primary { background: rgb(0, 135, 88); border-color: rgb(0, 135, 88); width: 100%; border-radius: 30px; padding: 8px 0px; }

.mini_cart .btn.btn-primary:hover { background: transparent; color: rgb(0, 135, 88); }

.mini_flex { display: flex; justify-content: space-between; margin-bottom: 15px; }

.mini_flex small { color: rgb(0, 0, 0); }

.mini_cart_data { padding-bottom: 15px; }

.min-cart_row, .mini_cart_data { display: flex; align-items: center; }

.min-cart_row { width: calc(100% - 20px); }

.mini_cart_data_img { margin-right: 0px; width: 80px; }

.mini_cart_data_cont { width: calc(100% - 80px); padding-left: 10px; }

.mini_cart_itemremove { width: 20px; text-align: right; }

