.siq-share-header, .siq-share-footer { position: absolute; width: 100%; z-index: 1; display: flex; align-items: center; visibility: hidden; }

.siq-share-header { top: -100%; justify-content: space-between; padding: 10px; align-items: flex-start; }

.siq-share-footer { justify-content: center; bottom: -100%; }

.siq-sshare-cont:hover .siq-share-header, .siq-sshare-cont:hover .siq-share-footer { visibility: visible; }

.siq-sshare-cont:hover .siq-share-header { top: 0px; }

.siq-sshare-cont:hover .siq-share-footer { bottom: 10px; }

.siq-sshare-cont { width: 400px; height: 260px; border-radius: 6px; cursor: move; box-shadow: rgba(0, 0, 0, 0.2) 0px 2px 6px 0px; position: absolute; top: 50px; left: 50px; z-index: 2147483647 !important; }

.siq-sshare-cont:hover::before { content: ""; height: 74px; width: 100%; position: absolute; z-index: 1; bottom: 0px; border-radius: 6px 6px 0px 0px; transform: rotate(180deg); background: linear-gradient(rgba(0, 0, 0, 0.6) 0px, rgba(0, 0, 0, 0) 100%); }

.siq-sshare-cont video { width: 100%; height: 100%; }

.siq-time-cont { background-color: rgb(0, 0, 0); color: rgb(255, 255, 255); padding: 4px 13px; border-radius: 3px; font-size: 14px; }

.zsiq_media_videohdr { z-index: 4; }

.siq-circle-btn { height: 40px; width: 40px; border-radius: 100%; display: flex; align-items: center; justify-content: center; background-color: rgb(255, 255, 255); color: rgb(102, 102, 102); cursor: pointer; }

.siq-circle-btn:not(:first-child) { margin-left: 15px; }

.siq-circle-btn.zsiqmico-maxscreen { background-color: rgb(0, 0, 0); color: rgb(255, 255, 255); font-size: 16px; }

.siq-circle-btn.zsiqmico-endcall { background-color: rgb(255, 96, 96); color: rgb(255, 255, 255); }

.siq-circle-btn.zsiqmico-pickcall { background-color: rgb(56, 182, 38); color: rgb(255, 255, 255); }

.zsiq-newtheme.siqembed.attach-preview { height: 100% !important; width: 100% !important; bottom: 0px !important; right: 0px !important; }

.zsiq-newtheme.siqembed.attach-preview:not(.siq_rht, siq_lft) { top: 0px !important; left: 0px !important; }

body:not(.new_prv, [signaturepreview="true"], .new_widget) .siqtrans.siqanim { animation: 1s ease-in-out 0s 1 normal none running zsiqcwanim; transform: translate(0px) !important; }

